import{_ as t,o as s,a as e,b as n}from"./app.DKoEZOcr.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"工具接口","link":"/api/SIMD-API/basic_api/tool_interface/tool_interface"},{"text":"系统初始化","link":"/api/SIMD-API/basic_api/tool_interface/system_init/system_init"},{"text":"InitSocState","link":"/api/SIMD-API/basic_api/tool_interface/system_init/InitSocState"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/tool_interface/system_init/InitSocState.md","filePath":"api/SIMD-API/basic_api/tool_interface/system_init/InitSocState.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),d={name:"api/SIMD-API/basic_api/tool_interface/system_init/InitSocState.md"};function l(p,a,r,i,c,o){return s(),e("div",null,[...a[0]||(a[0]=[n(`<div><article class="markdown-body"><h1>InitSocState</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_common_intf.h&quot;</code>。</p><p>本接口对AI Core的全局状态进行初始化，包括AIC（Cube Core）与AIV（Vector Core）的公共状态及各自特有状态。由于不同产品的实现存在差异，实际执行的初始化项也有所不同。</p><p><strong>接口涉及的全部初始化操作汇总如下：</strong></p><table><thead><tr><th>状态类别</th><th>初始化内容</th></tr></thead><tbody><tr><td>公共状态</td><td>初始化<a href="../../atomic_operations/DisableDmaAtomic.html">原子累加状态</a>，关闭数据搬运随路原子操作功能。</td></tr><tr><td>公共状态</td><td>初始化<a href="../../memory_vector_compute/SIMD_compute/mask.html#mask-mode">Mask工作模式</a>为Normal模式。</td></tr><tr><td>公共状态</td><td>初始化<a href="../../memory_vector_compute/type_conversion_aux_config/SetDeqScale.html#func1">用于AddDeqRelu/CastDequant/Cast的s322fp16场景的scale量化参数</a>为1。</td></tr><tr><td>公共状态</td><td>初始化<a href="../../special_register_access/SetCtrlSpr_ISASI.html#tab-950">CTRL寄存器</a>中除<code>CTRL[48]</code>以外的比特位为默认值。</td></tr><tr><td>公共状态</td><td>初始化<a href="../../atomic_operations/SetStoreAtomicConfig_ISASI.html">原子操作开启位与原子操作类型</a>，为无效的原子操作类型。</td></tr><tr><td>AIC</td><td>初始化<a href="../../cube_compute_ISASI/cube_load_aux_config/SetLoadDataPaddingValue.html#%E5%8A%9F%E8%83%BD%E8%AF%B4%E6%98%8E">LoadData（卷积数据搬运）接口调用时Pad填充的数值</a>为0。</td></tr><tr><td>AIC</td><td>初始化<a href="../../cube_compute_ISASI/cube_load_aux_config/SetLoadDataBoundary.html#%E5%8A%9F%E8%83%BD%E8%AF%B4%E6%98%8E">使用LoadData（卷积数据搬运）时L1 Buffer（A1/B1）的边界值</a>为0，表示无边界。</td></tr><tr><td>AIV</td><td>将<a href="../../memory_vector_compute/SIMD_compute/mask.html">Mask</a>配置为全1，表示所有数都参与计算。</td></tr><tr><td>AIV</td><td><a href="../../memory_vector_compute/data_move_aux_config/ResetLoopModePara.html">重置loop mode的参数</a>。</td></tr></tbody></table><p><strong>各产品实际执行的初始化项如下：</strong></p><div data-filter="950"><p><strong>表1</strong> 针对Ascend 950PR/Ascend 950DT本接口执行的初始化项</p><table><thead><tr><th>状态类别</th><th>初始化内容</th></tr></thead><tbody><tr><td>公共状态</td><td>原子累加状态</td></tr><tr><td>公共状态</td><td>Mask工作模式</td></tr><tr><td>公共状态</td><td>用于AddDeqRelu/CastDequant/Cast的s322fp16场景的scale量化参数</td></tr><tr><td>公共状态</td><td>CTRL寄存器</td></tr><tr><td>公共状态</td><td>原子操作开启位与原子操作类型</td></tr><tr><td>AIC</td><td>LoadData（卷积数据搬运）接口调用时Pad填充的数值</td></tr><tr><td>AIV</td><td>Mask</td></tr><tr><td>AIV</td><td>loop mode的参数</td></tr></tbody></table></div><div data-filter="A3"><p><strong>表2</strong> 针对Atlas A3 训练系列产品/Atlas A3 推理系列产品本接口执行的初始化项</p><table><thead><tr><th>状态类别</th><th>初始化内容</th></tr></thead><tbody><tr><td>公共状态</td><td>原子累加状态</td></tr><tr><td>公共状态</td><td>Mask工作模式</td></tr><tr><td>AIC</td><td>LoadData（卷积数据搬运）接口调用时Pad填充的数值</td></tr><tr><td>AIC</td><td>使用LoadData（卷积数据搬运）时L1 Buffer（A1/B1）的边界值</td></tr><tr><td>AIV</td><td>Mask</td></tr></tbody></table></div><div data-filter="910b"><p><strong>表3</strong> 针对Atlas A2 训练系列产品/Atlas A2 推理系列产品本接口执行的初始化项</p><table><thead><tr><th>状态类别</th><th>初始化内容</th></tr></thead><tbody><tr><td>公共状态</td><td>原子累加状态</td></tr><tr><td>公共状态</td><td>Mask工作模式</td></tr><tr><td>AIC</td><td>LoadData（卷积数据搬运）接口调用时Pad填充的数值</td></tr><tr><td>AIC</td><td>使用LoadData（卷积数据搬运）时L1 Buffer（A1/B1）的边界值</td></tr><tr><td>AIV</td><td>Mask</td></tr></tbody></table></div><div data-filter="310p"><p><strong>表4</strong> 针对Atlas 推理系列产品AI Core和Atlas 推理系列产品Vector Core本接口执行的初始化项</p><table><thead><tr><th>状态类别</th><th>初始化内容</th></tr></thead><tbody><tr><td>公共状态</td><td>原子累加状态</td></tr></tbody></table></div><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">InitSocState</span><span class="p">()</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p>无</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>在实际运行中，这些值可能被前序执行的算子修改，若不调用该接口进行初始化，非预期的值可能导致计算结果出现精度错误。</p><p>例如前序算子使用Counter模式但未重置为Normal模式，当前算子以默认的Normal模式设置Mask时，会导致Mask设置不符合预期，进而引发精度错误。</p></li><li><p>在<a href="../../../../../guide/programming_guide/programming_model/ai_core_simd_programming/tpipe_tque_programming/tpipe_tque_principles.html">TPipe框架编程</a>中，初始化过程由TPipe完成，无需开发者关注；在<a href="../../../../../guide/programming_guide/programming_model/ai_core_simd_programming/cpp_tensor_programming/static_tensor_programming.html">静态Tensor编程</a>的场景中，用户必须在核函数（Kernel）入口处调用此函数来初始化AI Core状态。</p></li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 静态Tensor编程方式中需要开发者手动调用InitSocState()接口初始化全局状态寄存器。</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">InitSocState</span><span class="p">();</span>
<span class="w">    </span><span class="n">KernelAdd</span><span class="w"> </span><span class="n">op</span><span class="p">;</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Init</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">);</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Process</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const A=t(d,[["render",l]]);export{_ as __pageData,A as default};
